/**
 * @summary Delete every pending article (draft + scheduled). Never touches published.
 */
export const DeleteAllPendingArticlesResponse = zod.object({
  deleted: zod.number(),
});

/**
 * @summary Publish every pending article (draft + scheduled) immediately. Never touches published.
 */
export const PublishAllPendingArticlesResponse = zod.object({
  published: zod.number(),
});

/**
 * @summary Force every draft into its scheduled slot now (skip the 48h auto-lock). Does not publish early; scheduled/published untouched.
 */
